+    if (path.size() >= options_.max_depth) {
+        --visit;
+        return;
+    }
+    for (const auto& tr : object.transitions) {
+        if (tr.src != state.name) {
+            continue;
+        }
+        std::size_t next = object.states.size();
+        for (std::size_t i = 0; i < object.states.size(); ++i) {
+            if (object.states[i].name == tr.dst) {
