+        if (next == object.states.size()) {
+            continue;
+        }
+        path.push_back(tr.func);
+        state_dfs(object, next, path, visits, out);
+        path.pop_back();
+        if (out.size() >= options_.max_flows) {
+            options_.truncated = true;
+        }
+    }
